INSERT INTO dbo.TB_SY_HUMOR (id_humor, nm_humor, ds_humor) VALUES
(1, N'Feliz', N'Dia leve, com vontade de sorrir e de estar com gente.'),
(2, N'Grato', N'Reconhecendo coisas boas que aconteceram, mesmo pequenas.'),
